CREATE OR REPLACE FUNCTION get_appraisal_ratio(ticker VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_alpha3y NUMERIC;
    v_vol3y NUMERIC;
    v_rsquared3y NUMERIC;
    v_appraisal_ratio NUMERIC;
BEGIN
    SELECT
        (risk3y->'risk_measures_3y'->>'Alpha_3Y')::numeric,
        (risk3y->'risk_measures_3y'->>'Volatility_3Y')::numeric,
        (risk3y->'risk_measures_3y'->>'R_Squared_3Y')::numeric / 100
    INTO
        v_alpha3y,
        v_vol3y,
        v_rsquared3y
    FROM risk_metrics
    WHERE investmentref = ticker;

    IF v_vol3y IS NULL OR v_vol3y = 0 OR v_rsquared3y IS NULL OR v_rsquared3y >= 1 OR v_alpha3y IS NULL THEN
        RETURN NULL;
    END IF;

    v_appraisal_ratio := v_alpha3y / (v_vol3y * POWER(1 - v_rsquared3y, 0.5));
    RETURN v_appraisal_ratio;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_appraisal_ratio(ticker VARCHAR, period VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_alpha NUMERIC;
    v_vol NUMERIC;
    v_rsquared NUMERIC;
    risk_data JSONB;
BEGIN
    SELECT
        CASE
            WHEN period = '3y' THEN risk3y
            WHEN period = '5y' THEN risk5y
            WHEN period = '10y' THEN risk10y
            ELSE NULL
        END
    INTO risk_data
    FROM risk_metrics
    WHERE investmentref = ticker;

    IF risk_data IS NULL THEN
        RETURN NULL;
    END IF;

    v_alpha := (risk_data->('risk_measures_' || period)->>('Alpha_' || upper(period)))::numeric;
    v_vol := (risk_data->('risk_measures_' || period)->>('Volatility_' || upper(period)))::numeric;
    v_rsquared := (risk_data->('risk_measures_' || period)->>('R_Squared_' || upper(period)))::numeric / 100;

    IF v_vol IS NULL OR v_vol = 0 OR v_rsquared IS NULL OR v_rsquared >= 1 OR v_alpha IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN v_alpha / (v_vol * POWER(1 - v_rsquared, 0.5));
END;
$$ LANGUAGE plpgsql;

