-- Step 1 (DDL): Define the log table to capture style drift events.
CREATE TABLE IF NOT EXISTS style_drift_log (
    log_id SERIAL PRIMARY KEY,
    fund_ticker VARCHAR(20),
    old_beta NUMERIC,
    new_beta NUMERIC,
    old_rsquared NUMERIC,
    new_rsquared NUMERIC,
    log_timestamp TIMESTAMP
);

-- Step 2 (DDL): Create the trigger function that contains the logging logic.
CREATE OR REPLACE FUNCTION log_style_drift()
RETURNS TRIGGER AS $$
DECLARE
    -- Declare variables to hold old and new risk values.
    old_beta_3y NUMERIC := (OLD.risk3y->'risk_measures_3y'->>'Beta_3Y')::numeric;
    new_beta_3y NUMERIC := (NEW.risk3y->'risk_measures_3y'->>'Beta_3Y')::numeric;
    old_rsquared_3y NUMERIC := (OLD.risk3y->'risk_measures_3y'->>'R_Squared_3Y')::numeric;
    new_rsquared_3y NUMERIC := (NEW.risk3y->'risk_measures_3y'->>'R_Squared_3Y')::numeric;
BEGIN
    -- Sub-step 2a: Check if the change in beta or r-squared exceeds the thresholds defined in "Style Drift" (ID: 79).
    IF ABS(new_beta_3y - old_beta_3y) > 0.15 OR ABS(new_rsquared_3y - old_rsquared_3y) > 10 THEN
        -- Sub-step 2b: If a significant drift is detected, insert a record into the log table.
        INSERT INTO style_drift_log (fund_ticker, old_beta, new_beta, old_rsquared, new_rsquared, log_timestamp)
        VALUES (NEW.investmentref, old_beta_3y, new_beta_3y, old_rsquared_3y, new_rsquared_3y, NOW());
    END IF;
    -- Return NEW to allow the original UPDATE operation to proceed.
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Step 3 (DDL): Create the trigger and attach it to the risk_metrics table.
-- This trigger will fire AFTER every UPDATE on the table.
CREATE OR REPLACE TRIGGER trg_risk_metrics_style_drift
AFTER UPDATE ON risk_metrics
FOR EACH ROW
EXECUTE FUNCTION log_style_drift();

ALTER TABLE funds ADD COLUMN IF NOT EXISTS rrei_score NUMERIC(10, 4);

-- Step 2 (DDL): Create the function to encapsulate the calculation logic.
-- This function takes a fund's ticker symbol and returns its RREI score.
CREATE OR REPLACE FUNCTION calculate_rrei(p_tickersym VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    -- Declare variables to hold the intermediate values.
    v_roc NUMERIC;
    v_volatility_3y NUMERIC;
BEGIN
    -- Sub-step 2a: Calculate 'Return on Cost (ROC)' (Knowledge ID: 2).
    SELECT (p.returnmetrics->'fund_returns'->>'Return_1Y')::numeric /
           NULLIF((f.fundmetrics->>'Expense_Net')::numeric, 0)
    INTO v_roc
    FROM funds f
    JOIN performance p ON f.tickersym = p.productref
    WHERE f.tickersym = p_tickersym;

    -- Sub-step 2b: Get the 3-year volatility.
    SELECT (risk3y->'risk_measures_3y'->>'Volatility_3Y')::numeric
    INTO v_volatility_3y
    FROM risk_metrics
    WHERE investmentref = p_tickersym;

    -- Sub-step 2c: Return the final RREI score, handling potential division by zero.
    IF v_volatility_3y IS NULL OR v_volatility_3y = 0 OR v_roc IS NULL THEN
        RETURN NULL;
    ELSE
        RETURN v_roc / v_volatility_3y;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Step 3 (DML): Update the funds table by applying the new function to each fund.
UPDATE funds
SET rrei_score = calculate_rrei(tickersym);

CREATE OR REPLACE FUNCTION calculate_adc(p_transport_id VARCHAR(20))
RETURNS DECIMAL AS $$
DECLARE
    total_cost DECIMAL;
    total_tons DECIMAL;
BEGIN
    SELECT SUM(f.transportcostsusd) INTO total_cost
    FROM financials f
    JOIN transportation t ON f.findistref = t.transportdistref
    WHERE t.transportregistry = p_transport_id;

    SELECT (delivery_metrics -> 'delivery_capacity' ->> 'total_tons')::DECIMAL INTO total_tons
    FROM transportation 
    WHERE transportregistry = p_transport_id;

    IF total_tons IS NULL OR total_tons <= 0 THEN
        RAISE EXCEPTION 'Invalid or zero delivery tons for ID %',
        p_transport_id;
    END IF;

    RETURN total_cost / total_tons;
END;
$$ LANGUAGE plpgsql;

